import sys, os, json; sys.path.insert(0, os.path.dirname(__file__))
from sn_admin import client, SCOPE
r = client.get("/api/now/table/cmdb_ci_service", params={"sysparm_fields": "name,sys_id", "sysparm_limit": 50})
print("services:", r.status_code, [(x["name"], x["sys_id"][:6]) for x in r.json().get("result", [])][:30])
r = client.get("/api/now/table/sys_dictionary", params={"sysparm_query": f"name=incident^element={SCOPE}ai_enabled", "sysparm_fields": "element,default_value,mandatory"})
print("ai_enabled dict:", r.json().get("result"))
r = client.get("/api/now/table/sys_script", params={"sysparm_query": "collection=incident^sys_scope.scope=x_2215032_ai_inc_0", "sysparm_fields": "name,active,when,action_insert,action_update"})
print("business rules in scope:", r.status_code, [(x["name"], x["active"], x["when"], x["action_insert"], x["action_update"]) for x in r.json().get("result", [])])
r = client.get("/api/now/table/sys_script", params={"sysparm_query": "collection=incident^active=true^nameLIKEHuman Lock", "sysparm_fields": "name,active,sys_scope"})
print("human lock rules:", [(x["name"], x["active"]) for x in r.json().get("result", [])])
